 Com<IDXGIFactory4>factory;check(CreateDXGIFactory2(0,IID_PPV_ARGS(&factory)),"WARP factory");Com<IDXGIAdapter>adapter;check(factory->EnumWarpAdapter(IID_PPV_ARGS(&adapter)),"WARP adapter");Com<ID3D12Device>device;check(D3D12CreateDevice(adapter.Get(),D3D_FEATURE_LEVEL_11_0,IID_PPV_ARGS(&device)),"WARP device");
 D3D12_DESCRIPTOR_RANGE range{};range.RangeType=D3D12_DESCRIPTOR_RANGE_TYPE_SRV;range.NumDescriptors=5;D3D12_ROOT_PARAMETER params[2]{};params[0].ParameterType=D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;params[0].DescriptorTable={1,&range};params[0].ShaderVisibility=D3D12_SHADER_VISIBILITY_PIXEL;params[1].ParameterType=D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;params[1].Constants={0,0,8};params[1].ShaderVisibility=D3D12_SHADER_VISIBILITY_PIXEL;D3D12_STATIC_SAMPLER_DESC sampler{};sampler.Filter=D3D12_FILTER_MIN_MAG_MIP_LINEAR;sampler.AddressU=sampler.AddressV=sampler.AddressW=D3D12_TEXTURE_ADDRESS_MODE_CLAMP;sampler.MaxLOD=D3D12_FLOAT32_MAX;sampler.ComparisonFunc=D3D12_COMPARISON_FUNC_ALWAYS;sampler.ShaderVisibility=D3D12_SHADER_VISIBILITY_PIXEL;D3D12_ROOT_SIGNATURE_DESC rootDesc{2,params,1,&sampler,D3D12_ROOT_SIGNATURE_FLAG_ALLOW_INPUT_ASSEMBLER_INPUT_LAYOUT};Com<ID3DBlob>blob,error;check(D3D12SerializeRootSignature(&rootDesc,D3D_ROOT_SIGNATURE_VERSION_1,&blob,&error),"Serialize root");Com<ID3D12RootSignature>root;check(device->CreateRootSignature(0,blob->GetBufferPointer(),blob->GetBufferSize(),IID_PPV_ARGS(&root)),"Create root");
 auto compile=[](const char* name,const char* profile){Com<ID3DBlob>b,e;HRESULT r=D3DCompile(kShaders,sizeof(kShaders)-1,"confidence.hlsl",nullptr,nullptr,name,profile,D3DCOMPILE_OPTIMIZATION_LEVEL3|D3DCOMPILE_WARNINGS_ARE_ERRORS,0,&b,&e);if(FAILED(r)){if(e)std::cerr<<std::string((char*)e->GetBufferPointer(),e->GetBufferSize());check(r,name);}return b;};auto vs=compile("VS","vs_5_0");
 std::array<Com<ID3D12PipelineState>,3>pipelines;const char* names[]={"PSUnpack","PSPresent","PSMotion"};DXGI_FORMAT formats[]={DXGI_FORMAT_R8G8B8A8_UNORM,DXGI_FORMAT_B8G8R8A8_UNORM,DXGI_FORMAT_R16G16_FLOAT};for(int i=0;i<3;++i){auto ps=compile(names[i],"ps_5_0");D3D12_GRAPHICS_PIPELINE_STATE_DESC d{};d.pRootSignature=root.Get();d.VS={vs->GetBufferPointer(),vs->GetBufferSize()};d.PS={ps->GetBufferPointer(),ps->GetBufferSize()};d.BlendState.RenderTarget[0].RenderTargetWriteMask=D3D12_COLOR_WRITE_ENABLE_ALL;d.SampleMask=UINT_MAX;d.RasterizerState.FillMode=D3D12_FILL_MODE_SOLID;d.RasterizerState.CullMode=D3D12_CULL_MODE_NONE;d.RasterizerState.DepthClipEnable=TRUE;d.PrimitiveTopologyType=D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE;d.NumRenderTargets=1;d.RTVFormats[0]=formats[i];d.SampleDesc.Count=1;Com<ID3D12PipelineState>p;check(device->CreateGraphicsPipelineState(&d,IID_PPV_ARGS(&p)),names[i]);pipelines[i]=p;std::cout<<names[i]<<": compiled and WARP PSO validated\n";}

